async function main() {
  const env = parse(readFileSync(resolve(ROOT, ".env")));
  const url = env.DATABASE_URL;
  if (!url) throw new Error("DATABASE_URL missing from .env");
  if (!url.includes("ep-wild-tree")) {
    console.warn(
      `\u26a0 target DB host is not the expected empowerher DB:\n  ${url.slice(0, 60)}\u2026`
    );
  }
  const db = drizzle(url);

  console.log(`Seeding ${STORIES.length} stories\u2026`);

  let inserted = 0;
  for (const s of STORIES) {
    // neon-http has no transactions — insert sequentially.
    const [row] = await db
      .insert(hervoiceTable)
      .values({
        slug: s.slug,
        title: s.title,
        description: s.description,
        content: s.content,
        image: s.image,
        imageAlt: s.imageAlt,
        imageCredit: s.imageCredit,
        authorName: s.authorName,
        authorBio: s.authorBio,
        authorPosition: s.authorPosition,
        authorInstagram: s.authorInstagram,
        authorFacebook: s.authorFacebook,
        authorLinkedin: s.authorLinkedin,
        messageToWorld: s.messageToWorld,
        hide: s.hide,
        createdAt: new Date(s.createdAt),
      })
      .onConflictDoNothing({ target: hervoiceTable.slug })
      .returning({ slug: hervoiceTable.slug });

    if (row) {
      inserted++;
      console.log(`  \u2713 ${row.slug}`);
    } else {
      console.log(`  \u2013 ${s.slug} (already exists, skipped)`);
    }
  }

  console.log(`\nDone. Inserted ${inserted}/${STORIES.length}.`);
}

main().catch((err) => {
  console.error(err);
  process.exit(1);
});
